
ON CONFLICT (name) DO NOTHING;

DO $$
DECLARE
    v_map_id INTEGER;
    v_group_id INTEGER;
BEGIN
    SELECT id INTO v_map_id FROM map_t WHERE name = 'de_nuke';

    SELECT id INTO v_group_id FROM vertex_group_t WHERE name = 'worldspawn[_undefined_]';

    SELECT id INTO v_group_id FROM vertex_group_t WHERE name = 'func_breakable[_undefined_]';

    SELECT id INTO v_group_id FROM vertex_group_t WHERE name = 'func_breakable_surf[_undefined_]';

    SELECT id INTO v_group_id FROM vertex_group_t WHERE name = 'func_door_rotating[door_reactoral]';

    SELECT id INTO v_group_id FROM vertex_group_t WHERE name = 'func_door_rotating[door_reactorar]';

    SELECT id INTO v_group_id FROM vertex_group_t WHERE name = 'func_door_rotating[door_reactorbr]';

    SELECT id INTO v_group_id FROM vertex_group_t WHERE name = 'func_door_rotating[door_reactorbl]';

    SELECT id INTO v_group_id FROM vertex_group_t WHERE name = 'func_illusionary[_undefined_]';

    SELECT id INTO v_group_id FROM vertex_group_t WHERE name = 'func_door_rotating[door_bombsitea]';

    SELECT id INTO v_group_id FROM vertex_group_t WHERE name = 'func_brush[_undefined_]';

    SELECT id INTO v_group_id FROM vertex_group_t WHERE name = 'func_buyzone[_undefined_]';

    SELECT id INTO v_group_id FROM vertex_group_t WHERE name = 'func_bomb_target[A]';

    SELECT id INTO v_group_id FROM vertex_group_t WHERE name = 'func_bomb_target[B]';

    SELECT id INTO v_group_id FROM vertex_group_t WHERE name = 'func_brush[portal_brush03]';

    SELECT id INTO v_group_id FROM vertex_group_t WHERE name = 'func_brush[portal_brush04]';

    SELECT id INTO v_group_id FROM vertex_group_t WHERE name = 'func_brush[portal_brush02]';

    SELECT id INTO v_group_id FROM vertex_group_t WHERE name = 'func_brush[portal_brush01]';
END $$;
